/*
 * CalDAVSync.h - shared types and cross-file declarations. Resource IDs
 * live in CalDAVSyncRsc.h (a separate, PalmOS.h-free header, generated by
 * pilrc from MainEn.rcp) - same split BitWarden.h uses and for the same
 * reason (pilrc can't parse a real `#include <PalmOS.h>`).
 */
#ifndef CALDAVSYNC_H
#define CALDAVSYNC_H

#include <PalmOS.h>
#include "CalDAVSyncRsc.h"
#include "enccore.h"

#define cddvMaxSlots      8
#define cddvAliasLen      24
#define cddvUrlLen        128
#define cddvPathLen       96
#define cddvUserLen       64
#define cddvSecretMaxLen  256	/* app password or OAuth refresh token, ciphertext */
#define cddvSecretPlainLen 128	/* plaintext shadow buffer cap for the Edit form's own "Show" masking - SlotEditForm.c, independent of cddvSecretMaxLen (ciphertext) */
#define cddvSyncErrMsgLen 64
#define cddvGoogleClientIdLen 96	/* Google OAuth 2.0 Client ID (~72 chars typical) - lives on the Palm only, never on WiRSa */
/* Google's own docs say client_secret is optional for a "Desktop app"
 * OAuth client - in practice, its token endpoint still rejects both the
 * authorization_code and refresh_token grants without one ("client_secret
 * is missing"), confirmed against a real client. So this is required
 * despite the docs, same "lives on the Palm only" treatment as Client ID. */
#define cddvGoogleClientSecretLen 48	/* e.g. "GOCSPX-..." (~35 chars typical) */
#define cddvPrefsVersion  5

/* Matches WiRSa caldav_relay.cpp's own UNIX_TO_PALM_EPOCH exactly (the two
 * ends must agree - see SyncEngine.c's SYNC_REQUEST clock field, appended
 * 2026-09-17 so WiRSa can compute the sync window from the Palm's own
 * clock instead of depending on NTP succeeding on WiRSa's network every
 * time). Palm epoch (1/1/1904) minus Unix epoch (1/1/1970) = 66 years. */
#define cddvUnixToPalmEpoch 2082844800UL

typedef enum {
	cddvTypeCalDAV = 0,
	cddvTypeICloud = 1,
	cddvTypeGoogle = 2,
	cddvTypeICSFeed = 3
} CDDVServerType;

/* Shared past/future sync-window enum - same option list used by both the
 * global Preferences form and a slot's own override fields (SlotForm.c).
 * Values are ordinal indices into the popup lists, not raw day counts - the
 * day-count/none mapping lives once in DAVDb.c (SyncEngine.c's own sync-
 * window resolution) to avoid two places disagreeing on what "2mo" means. */
typedef enum {
	cddvPastNone = 0, cddvPast1Wk, cddvPast2Wk, cddvPast1Mo, cddvPast2Mo, cddvPast3Mo
} CDDVPastWindow;
typedef enum {
	cddvFuture2Wk = 0, cddvFuture1Mo, cddvFuture3Mo, cddvFuture6Mo, cddvFuture1Yr
} CDDVFutureWindow;

#define cddvPastWindowDefault   cddvPast2Mo
#define cddvFutureWindowDefault cddvFuture6Mo

typedef struct {
	char server[cddvUrlLen];		/* CalDAV: server URL. iCloud: shard hostname. Google: unused. ICSFeed: the feed URL. */
	char path[cddvPathLen];		/* CalDAV: calendar path. iCloud: calendar name. Google: calendar ID. */
	char uuid[40];					/* iCloud principal UUID only - blank otherwise */
	char user[cddvUserLen];		/* CalDAV/iCloud username - blank for Google/ICSFeed */
	UInt8 secret[cddvSecretMaxLen];	/* Sec35 ciphertext - app password or OAuth refresh token */
	UInt16 secretLen;				/* 0 = none saved (e.g. ICS feed needs none) */
	char alias[cddvAliasLen];
	CDDVServerType serverType;
	Boolean ignoreOnSyncAll;
	/* Raw popup-list selection index, NOT a CDDVPastWindow/CDDVFutureWindow
	 * value directly - item 0 in both lists is "Default" (inherit
	 * p->pastDefault/futureDefault), so the real enum value is (sel - 1).
	 * Replaces a separate windowOverrideEnabled checkbox + enum pair (user
	 * feedback: a single "Sync: [from] to [to]" row where the popup itself
	 * carries the "Default" option is clearer than a checkbox gating two
	 * otherwise-meaningless-looking popups). See SyncEngine.c's
	 * ResolveWindow for the one place that does the -1 translation. */
	UInt8 pastOverrideSel;
	UInt8 futureOverrideSel;
	UInt32 lastSyncTime;			/* 0 = never synced */
	Boolean lastSyncOk;
	/* Appended fields (2026-09-18, user request: verbose per-slot status) -
	 * at the END, not interleaved, same "minimize churn on every existing
	 * byte-for-byte reader" discipline DAVDb.h's own CDDVEvent notes/
	 * isRepeating fields already established. See CDDVPrefs.c's own v1->v2
	 * migration for why bumping cddvPrefsVersion alone isn't enough here. */
	UInt16 lastSyncEventCount;		/* events synced on the last successful attempt */
	char lastSyncErrMsg[cddvSyncErrMsgLen];	/* empty if lastSyncOk, else the reason */
	/* Appended (v3) - Google's OAuth 2.0 Client ID, per slot. Not a secret
	 * (Google's own "Desktop app" client type treats it as public), so not
	 * Sec35-encrypted like secret[] above - plain text, same as path/server.
	 * Sent fresh in every SYNC_REQUEST; WiRSa never persists it - it must
	 * never hold resident, account-identifying state of its own. */
	char googleClientId[cddvGoogleClientIdLen];
	/* Appended (v4) - Google's OAuth Client Secret, required by Google's
	 * token endpoint in practice (see cddvGoogleClientSecretLen's own
	 * comment). Same treatment as googleClientId - plain text, sent fresh
	 * in every SYNC_REQUEST, never persisted on WiRSa. */
	char googleClientSecret[cddvGoogleClientSecretLen];
	/* Appended (v5, user request 2026-09-24) - every identifying/config
	 * field above (server/path/uuid/user/alias/googleClientId/
	 * googleClientSecret) is now Sec35 ciphertext in place, same treatment
	 * secret[]/secretLen already had from the start - only lastSyncTime/
	 * lastSyncOk/lastSyncEventCount/lastSyncErrMsg stay plaintext (WiRSa's
	 * own generated status text, not user-entered configuration). AES-CTR
	 * ciphertext is fixed-length and can contain a stray 0x00 anywhere, so
	 * each field needs its own explicit plaintext-length companion here -
	 * StrLen()/NUL-termination on the raw buffer is meaningless once
	 * encrypted. See CDDVSec35.h's per-field encrypt/decrypt helpers. */
	UInt16 serverLen;
	UInt16 pathLen;
	UInt16 uuidLen;
	UInt16 userLen;
	UInt16 aliasLen;
	UInt16 googleClientIdLen;
	UInt16 googleClientSecretLen;
	/* false only transiently, right after a v4-or-earlier prefs load
	 * migrated this slot's fields forward as plaintext - CalDAVSync.c's
	 * StartApplication runs a one-time CDDVEncryptSlotFieldsIfNeeded pass
	 * (Sec35 is guaranteed unlocked by then, the app's own launch gate)
	 * that encrypts them in place and flips this true. Always true again
	 * immediately after, for the rest of this slot's life. */
	Boolean fieldsEncrypted;
} CDDVSlot;

typedef struct {
	UInt16 version;
	CDDVPastWindow pastDefault;
	CDDVFutureWindow futureDefault;
	UInt8 activeSlot;
	CDDVSlot slots[cddvMaxSlots];
} CDDVPrefsType;

#endif
